$ErrorActionPreference='Stop'; function Open-Secret([string]$s){$v=ConvertTo-SecureString -String $s;$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($v);try{[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p)}};try{$dir=Join-Path $env:LOCALAPPDATA 'AstorEsbEnrollment';[IO.Directory]::CreateDirectory($dir)|Out-Null;$path=Join-Path $dir '3370588b-0742-11e0-b9c1-001a64c3f566.json.dpapi';$inputText=[Console]::In.ReadToEnd();if([string]::IsNullOrWhiteSpace($inputText)){if([IO.File]::Exists($path)){$text=Open-Secret ([IO.File]::ReadAllText($path));[Console]::Out.Write('DATA:'+ [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($text)));exit 0};$probe=Join-Path $dir ([Guid]::NewGuid().ToString('N')+'.probe');try{$protected=ConvertTo-SecureString -String 'cache-probe' -AsPlainText -Force|ConvertFrom-SecureString;[IO.File]::WriteAllText($probe,$protected);if((Open-Secret ([IO.File]::ReadAllText($probe))) -cne 'cache-probe'){throw 'probe'}}finally{if([IO.File]::Exists($probe)){[IO.File]::Delete($probe)}};[Console]::Out.Write('READY');exit 0};$text=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($inputText));if([IO.File]::Exists($path)){throw 'exists'};$protected=ConvertTo-SecureString -String $text -AsPlainText -Force|ConvertFrom-SecureString;$temp=$path+'.'+[Guid]::NewGuid().ToString('N')+'.tmp';[IO.File]::WriteAllText($temp,$protected);[IO.File]::Move($temp,$path);if((Open-Secret ([IO.File]::ReadAllText($path))) -cne $text){throw 'verify'};[Console]::Out.Write('SAVED')}catch{[Console]::Out.Write('CACHE_ERROR');exit 1}